import random
from statistics import NormalDist


def prob_between(mu, sigma, a, b):
    if sigma <= 0:
        raise ValueError('sigma must be positive')
    if a >= b:
        return 0.0
    dist = NormalDist(mu, sigma)
    return dist.cdf(b) - dist.cdf(a)


def value_at(mu, sigma, p):
    if sigma <= 0 or not 0 < p < 1:
        raise ValueError('need sigma > 0 and 0 < p < 1')
    return NormalDist(mu, sigma).inv_cdf(p)


def estimate_between(mu, sigma, a, b, n, seed):
    if sigma <= 0 or n < 1:
        raise ValueError('need sigma > 0 and n >= 1')
    rng = random.Random(seed)
    hits = 0
    for _ in range(n):
        x = rng.gauss(mu, sigma)
        if a < x <= b:
            hits += 1
    return hits / n
